        test("ReviewDiff send proof uses post-baseline user-turn attachment surface and composer-clean MAIN-world click",()->{String adapter=Files.readString(Path.of("chatgpt-bridge-extension/src/chatgpt-adapter.js"),StandardCharsets.UTF_8),background=Files.readString(Path.of("chatgpt-bridge-extension/src/background.js"),StandardCharsets.UTF_8),content=Files.readString(Path.of("chatgpt-bridge-extension/src/content.js"),StandardCharsets.UTF_8),manifest=Files.readString(Path.of("chatgpt-bridge-extension/manifest.json"),StandardCharsets.UTF_8);ok(adapter.contains("reviewDiffAttachmentTurnPresent"),"ReviewDiff attachment-turn confirmation helper is missing");ok(adapter.contains("slice(prepared.beforeUserMessages)"),"outgoing confirmation is not scoped after the delivery baseline");ok(adapter.contains("userTurnSurface(message)"),"post-Send proof is still restricted to the message-author node");ok(adapter.contains("conversation-turn-"),"post-Send proof does not prefer a complete ChatGPT conversation-turn container");ok(adapter.contains("ownsOnlyAuthoredMessage(turn, message)"),"preferred conversation-turn/article candidate bypasses authored-turn ownership guard");ok(adapter.contains("!ownsOnlyAuthoredMessage(parent, message)"),"fallback can cross into a neighboring authored turn");ok(adapter.contains("reviewDiffAttachmentCandidates(turn).some(nodeShowsDiffFile)"),"Sent confirmation does not require a file/attachment-like surface in the user turn");ok(adapter.contains("value.includes(\".diff\")"),"Sent confirmation does not look for a .diff artifact surface");ok(!adapter.contains("nodeMentionsFile"),"generic user-message text is still used as ReviewDiff delivery proof");ok(adapter.contains("diffTurnPresent && !present"),"Sent confirmation does not require the prepared composer attachment to have left");ok(adapter.contains("state: \"contaminated\""),"content-side composer contamination state is missing");ok(content.contains("post-baseline user-turn attachment surface"),"Sent diagnostic does not describe the actual confirmation proof");ok(content.contains("no post-baseline ReviewDiff .diff attachment surface"),"UnknownAfterSend diagnostic does not describe missing attachment proof");ok(background.contains("composer-dirty"),"MAIN-world Send click does not reject later composer text");int attempt=content.indexOf("OBS_REVIEW_SEND_ATTEMPT"),possible=content.indexOf("possibleSend = true;",attempt),sendStage=content.indexOf("stageTask(task, \"SendClicked\")",possible);ok(attempt>=0&&possible>attempt&&sendStage>possible,"SendClicked is still staged before a real possible-Send click");ok(manifest.contains("\"version\": \"0.2.11\""),"extension patch version was not advanced");});
        test("ReviewDiff DOM turn-boundary regression is wired into the standard test runner",()->{String runner=Files.readString(Path.of("run-tests.cmd"),StandardCharsets.UTF_8),domTest=Files.readString(Path.of("chatgpt-bridge-extension/test/chatgpt-adapter-dom.test.js"),StandardCharsets.UTF_8);ok(runner.contains("node chatgpt-bridge-extension\\test\\chatgpt-adapter-dom.test.js"),"standard test runner does not execute the DOM regression");ok(domTest.contains("same-turn sibling .diff file card was not accepted"),"positive same-turn DOM regression is missing");ok(domTest.contains("neighboring turn .diff crossed the authored-turn boundary"),"negative neighboring-turn DOM regression is missing");ok(domTest.contains("ordinary .diff message text was treated as attachment proof"),"ordinary-text negative DOM regression is missing");});
