        test("heavy Swing operations are dispatched through background workers",()->{String ui=Files.readString(Path.of("src/main/java/obs/rpkg/MainWindow.java"),StandardCharsets.UTF_8).replace("\r\n","\n").replace('\r','\n');ok(ui.contains("new SwingWorker<T,Void>()"),"shared Swing background runner missing");ok(ui.contains("runBackground(\"Prepare Apply\""),"Apply prepare still runs on EDT");ok(ui.contains("runBackground(\"Apply\""),"Apply execute still runs on EDT");ok(ui.contains("runBackground(\"Refresh Review\""),"Refresh Review still runs on EDT");ok(ui.contains("runBackground(\"Finalize\""),"Finalize still runs on EDT");ok(ui.contains("runBackground(\"Repository Snapshot\""),"Repository Snapshot export still runs on EDT");int applyStart=ui.indexOf("private void apply()");int applyEnd=ui.indexOf("private void continuePreparedApply",applyStart);ok(applyStart>=0&&applyEnd>applyStart,"Apply UI entry missing");String applyEntry=ui.substring(applyStart,applyEnd);ok(!applyEntry.contains("core.readPackage("),"Apply UI entry still opens/parses ZIP on EDT before Prepare");});
