        test("semantic External Interaction cancel retains prepared content state and blocks post-send rewrite",()->{StateStore st=new StateStore(tmp.resolve("interaction-cancel-state"));ChatBridgeService s=serviceWithChat(st,"convK2345678",1711);Core.ChatBinding b=s.bind("cs","convK2345678");Core.ChatTaskInfo t=s.enqueueReview(changeSet("cs","work"),review(tmp.resolve("interaction-cancel.diff"),"interaction-review","x"),b,true);ok(s.externalInteractions().stream().anyMatch(x->x.interactionId().equals(t.taskId())&&x.cancellable()),"queued semantic interaction missing");s.claim("convK2345678",1711);s.stagePreparing(t.taskId(),1711,"convK2345678");Core.ExternalInteraction cancelled=s.cancelExternalInteraction(t.taskId());eq(cancelled.state(),"Cancelled","prepared interaction not cancelled");ok(cancelled.message().contains("prepared content retained"),"prepared cancel did not retain-content truth");eq(s.taskInfo(t.taskId()).status(),"Cancelled","technical task did not stop after prepared cancel");Core.ChatTaskInfo sending=s.enqueueReview(changeSet("cs","work"),review(tmp.resolve("interaction-send.diff"),"send-review","y"),b,true);s.claim("convK2345678",1711);s.stagePreparing(sending.taskId(),1711,"convK2345678");s.stageSendClicked(sending.taskId(),1711,"convK2345678");Core.ExternalInteraction visible=s.externalInteractions().stream().filter(x->x.interactionId().equals(sending.taskId())).findFirst().orElseThrow();eq(visible.state(),"Sending","active send-retry phase is not projected semantically");ok(!visible.cancellable(),"SendClicked interaction advertised unsafe Cancel");expect(Core.CHAT_BRIDGE_FAILED,()->s.cancelExternalInteraction(sending.taskId()));eq(s.taskInfo(sending.taskId()).status(),"SendClicked","cancel rewrote possible-send truth");});
        test("External Interaction list is current/actionable and terminal retry gets new identity",()->{Path stateRoot=tmp.resolve("interaction-history-state");StateStore st=new StateStore(stateRoot);ChatBridgeService service=serviceWithChat(st,"convM2345678",1811);Core.ChatBinding b=service.bind("cs","convM2345678");Core.ChatTaskInfo sent=service.enqueueReview(changeSet("cs","work"),review(tmp.resolve("terminal.diff"),"terminal","x"),b,true);service.claim("convM2345678",1811);service.stagePreparing(sent.taskId(),1811,"convM2345678");service.stageSendClicked(sent.taskId(),1811,"convM2345678");service.result(sent.taskId(),1811,"convM2345678","Sent","done");ok(service.externalInteractions().stream().noneMatch(x->x.interactionId().equals(sent.taskId())),"ordinary terminal success accumulated in semantic list");Core.ChatTaskInfo cancelled=service.enqueueReview(changeSet("cs","work"),review(tmp.resolve("cancelled.diff"),"cancelled","y"),b,true);service.cancelExternalInteraction(cancelled.taskId());ok(service.externalInteractions().stream().noneMatch(x->x.interactionId().equals(cancelled.taskId())),"Cancelled interaction accumulated in semantic list");Core.ChatTaskInfo retry=service.enqueueReview(changeSet("cs","work"),review(tmp.resolve("retry.diff"),"retry","z"),b,true);ok(!retry.taskId().equals(cancelled.taskId()),"retry reused cancelled interaction identity");Core.ExternalInteraction active=service.externalInteractions().stream().filter(x->x.interactionId().equals(retry.taskId())).findFirst().orElseThrow();ok(active.destination().contains("convM2345678"),"interaction destination hid exact conversation key");ok(active.source().endsWith(".diff"),"interaction source was not exposed");service.claim("convM2345678",1811);service.stagePreparing(retry.taskId(),1811,"convM2345678");service.stageSendClicked(retry.taskId(),1811,"convM2345678");service.result(retry.taskId(),1811,"convM2345678","UnknownAfterSend","uncertain");ok(service.externalInteractions().stream().anyMatch(x->x.interactionId().equals(retry.taskId())&&"UnknownAfterSend".equals(x.state())),"attention-requiring uncertainty disappeared from semantic list");ChatBridgeService restarted=serviceWithChat(new StateStore(stateRoot),"convM2345678",1811);ok(restarted.externalInteractions().stream().anyMatch(x->x.interactionId().equals(retry.taskId())),"persisted UnknownAfterSend uncertainty disappeared after restart");});
